"IZOD>20 kJ/m² 算韧（可做外壳）、<5 慎结构",
"HDT 要比工作温度高 20~30℃ 留安全余量",
"RTI（UL）是长期温升判据，与 HDT 两套语言",
"PA 分干湿态、玻纤分方向：条件标注别漏看"
