"非标料厚=高价+交期长：标准料厚 0.5/0.8/1.0/1.2/1.5/2.0/3.0mm（钢/铝通用阶梯）。",
"选厚逻辑：先功能取标准系列就近上靠，别画 1.1mm 让供应商定做。"
